// helpers
const inp = $input.first().json;
const empty = v => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);
const pick = (keys) => { const o = {}; for (const k of keys) if (!empty(inp[k])) o[k] = inp[k]; return o; };
const asObj = (v) => { if (empty(v)) return {}; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { throw new Error('EFX E_VALIDATION: JSON field is not valid JSON'); } } return v; };
const asArr = (v) => empty(v) ? [] : (Array.isArray(v) ? v : String(v).split(',').map(s => s.trim()).filter(Boolean));
const bool = (v, d) => empty(v) ? d : (v === true || String(v).toLowerCase() === 'true');
const passthru = { actor: empty(inp.actor) ? undefined : inp.actor, idempotencyKey: empty(inp.idempotencyKey) ? '' : String(inp.idempotencyKey) };

const REQUIRED = ["workflowId","Email_Created","Computer_Assigned","Phone_Assigned","BOSS_Access"];
const OPTIONAL = ["requestId","formId","Employee_Name","Email_Username","Email_Domain","Email_Temp_Password","Computer_Serial","Computer_Model","Computer_Type","Phone_Carrier","Phone_Model","Phone_Number","Phone_VM_Password","BOSS_TripReports","BOSS_Grievances","Incidents_Access","CAA_Access","Delivery_App_Access","Net_Promoter_Score_Access","IT_Notes"];
const DYN = ["BOSS_Cmte_","BOSS_CostSheet_"];
const data = Object.assign({}, asObj(inp.extra), pick(REQUIRED.concat(OPTIONAL)));
const missing = REQUIRED.filter(k => empty(data[k]));
if (missing.length) throw new Error('EFX E_VALIDATION: it_setup missing required field(s): ' + missing.join(', '));
const unknown = Object.keys(data).filter(k => !REQUIRED.includes(k) && !OPTIONAL.includes(k) && !DYN.some(p => k.startsWith(p)));
if (unknown.length) throw new Error('EFX E_VALIDATION: it_setup unknown field(s) (not in contract): ' + unknown.join(', '));
const YN = ['Yes', 'No'];
for (const k of ['Email_Created', 'Computer_Assigned', 'Phone_Assigned', 'BOSS_Access', 'Incidents_Access', 'CAA_Access', 'Delivery_App_Access', 'Net_Promoter_Score_Access']) if (!empty(data[k]) && !YN.includes(String(data[k]))) throw new Error('EFX E_VALIDATION: ' + k + ' must be Yes|No');
const DOMAINS = ['@team-group.com', '@robinsonsolutions.com', '@industrialappliedtech.com'];
if (!empty(data.Email_Domain) && !DOMAINS.includes(String(data.Email_Domain))) throw new Error('EFX E_VALIDATION: Email_Domain must be one of ' + DOMAINS.join('|'));
// The UI always posts these four as "No" when unchecked — mirror that so IT Results columns are never blank
for (const k of ['Incidents_Access', 'CAA_Access', 'Delivery_App_Access', 'Net_Promoter_Score_Access']) if (empty(data[k])) data[k] = 'No';
const options = { include: bool(inp.includeRecord, false) ? ['record'] : [], allowUnverified: bool(inp.allowUnverified, false) };
return [{ json: Object.assign({ fn: 'n8n_submitItSetup', args: [data, options] }, passthru) }];
